import math
def subgroup_sieve_bound(n, subgroup_orders):
    nfact = math.factorial(n)
    return sum((h / nfact) ** 2 for h in subgroup_orders)

# Point stabilizers in S_5: 5 subgroups of order 24
print(subgroup_sieve_bound(5, [24]*5))  # 0.2

def check_certificate(sigma, tau):
    n = len(sigma)
    visited = [False]*n; pos = 0; length = 0
    while not visited[pos]:
        visited[pos] = True; pos = sigma[pos]; length += 1
    if length != n: return False
    def sign(p):
        vis = [False]*len(p); cyc = 0
        for i in range(len(p)):
            if not vis[i]:
                cyc += 1; j = i
                while not vis[j]: vis[j] = True; j = p[j]
        return (-1)**(len(p)-cyc)
    return sign(sigma) == -1 or sign(tau) == -1

print(check_certificate((1,2,3,4,0), (1,0,2,3,4)))  # True
